const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const inge = @import("ru-soci-inge.zig"); const pull = @import("ru-carz-pull.zig"); const pipe = @import("ru-page-fetc.zig"); const cfgz = @import("cf-conf-load.zig");
const SELL = "{\"kind\":\"face\",\"id\":\"p1\",\"url\":\"https://www.facebook.com/groups/12/posts/p1\",\"text\":\"Toyota Fortuner 2017 số sàn, 84.000 km, máy dầu, bán gấp giá 520 triệu. Liên hệ 0966.353.678 ở Bình Dương\",\"auth\":\"Nguyen Van A\",\"src\":\"Mua ban oto\",\"posted\":1795000000000}";
const BUYR = "{\"kind\":\"zalo\",\"id\":\"z9\",\"url\":\"https://zalo.me/g/abc/z9\",\"text\":\"Cần mua Mazda CX-5 đời 2020 tầm 700tr, ai có bán liên hệ\",\"auth\":\"Tran B\"}";
const BADL = "{\"kind\":\"twit\",\"url\":\"https://x.com/1\",\"text\":\"nope\"}";
fn scal(dbzz: *sqli.Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
fn dropz(aren: std.mem.Allocator, srcd: []const u8, name: []const u8, data: []const u8) !void { try std.Io.Dir.cwd().createDirPath(std.testing.io, srcd); try std.Io.Dir.cwd().writeFile(std.testing.io, .{ .sub_path = try std.fs.path.join(aren, &.{ srcd, name }), .data = data }); }
test "ingest: dry-run counts, live saves pages and never refetches, file moves to done, same file again is all same, pull builds sell and buyer rows" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const srcd = try std.fs.path.join(aren.allocator(), &.{ dirz, "social-in" }); const conf: cfgz.Conf = .{};
    const data = SELL ++ "\n" ++ BUYR ++ "\n\n" ++ BADL ++ "\n"; try dropz(aren.allocator(), srcd, "a.jsonl", data); try dropz(aren.allocator(), srcd, "note.txt", "ignore me");
    const dryz = try inge.ingeRunz(null, std.testing.io, dirz, srcd, conf, allo, true); try std.testing.expectEqual(@as(u32, 1), dryz.file); try std.testing.expectEqual(@as(u32, 2), dryz.line); try std.testing.expectEqual(@as(u32, 1), dryz.bads); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM page;"));
    const live = try inge.ingeRunz(&dbzz, std.testing.io, dirz, srcd, conf, allo, false); try std.testing.expectEqual(@as(u32, 2), live.news); try std.testing.expectEqual(@as(u32, 1), live.bads); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM page WHERE code=200 AND vend='soci';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM page WHERE next>8000000000000000;")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM reco WHERE kind='json';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM outb WHERE kind='file';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM outb WHERE kind='rec';"));
    try std.testing.expectError(error.FileNotFound, std.Io.Dir.cwd().statFile(std.testing.io, try std.fs.path.join(aren.allocator(), &.{ srcd, "a.jsonl" }), .{})); _ = try std.Io.Dir.cwd().statFile(std.testing.io, try std.fs.path.join(aren.allocator(), &.{ srcd, "note.txt" }), .{}); var tras = try std.Io.Dir.cwd().openDir(std.testing.io, try std.fs.path.join(aren.allocator(), &.{ dirz, "trash" }), .{ .iterate = true }); defer tras.close(std.testing.io); var days: u32 = 0; var files: u32 = 0; var iter = tras.iterate(); while (try iter.next(std.testing.io)) |dayz| { days += 1; var dayd = try tras.openDir(std.testing.io, dayz.name, .{ .iterate = true }); defer dayd.close(std.testing.io); var itr2 = dayd.iterate(); while (try itr2.next(std.testing.io)) |ent| { try std.testing.expect(std.mem.startsWith(u8, ent.name, "social-") and std.mem.endsWith(u8, ent.name, "-a.jsonl")); files += 1; } } try std.testing.expectEqual(@as(u32, 1), days); try std.testing.expectEqual(@as(u32, 1), files);
    try dropz(aren.allocator(), srcd, "b.jsonl", SELL ++ "\n" ++ BUYR ++ "\n"); const again = try inge.ingeRunz(&dbzz, std.testing.io, dirz, srcd, conf, allo, false); try std.testing.expectEqual(@as(u32, 2), again.same); try std.testing.expectEqual(@as(u32, 0), again.news + again.chan);
    const nowz = pipe.nowzMill(std.testing.io); const pres = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, nowz, false); try std.testing.expectEqual(@as(u32, 2), pres.news); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE site='facebook.com' AND make='Toyota' AND pric=520000000 AND kmzz=84000 AND sell='private';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE site='zalo.me' AND make='Mazda' AND pric=0 AND sell='buyer' AND xtra LIKE '%700000000%';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon='0966353678' AND instr(text,'0966')=0;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE name='Nguyen Van A' AND kind='private';")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz WHERE cont<>'';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE sell='buyer' AND clus='' AND trim='';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE sell='private' AND clus<>'';")); }
test "privacy: with cont_priv_enab off no private name or phone reaches the contact book" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const srcd = try std.fs.path.join(aren.allocator(), &.{ dirz, "social-in" }); var conf: cfgz.Conf = .{}; conf.cont_priv_enab = false; try dropz(aren.allocator(), srcd, "a.jsonl", SELL ++ "\n"); _ = try inge.ingeRunz(&dbzz, std.testing.io, dirz, srcd, conf, allo, false); _ = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, pipe.nowzMill(std.testing.io), false); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz;")); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM cont WHERE name<>'' OR phon<>'';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE length(phsh)=17;")); }
test "ingest: a missing input folder is zero work, not an error; oversize lines are bad" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const nonz = try std.fs.path.join(aren.allocator(), &.{ dirz, "nope" }); const conf: cfgz.Conf = .{}; const rslt = try inge.ingeRunz(null, std.testing.io, dirz, nonz, conf, allo, true); try std.testing.expectEqual(@as(u32, 0), rslt.file + rslt.line + rslt.bads); try std.testing.expect(inge.recoChek(aren.allocator(), SELL, 20000) != null); try std.testing.expect(inge.recoChek(aren.allocator(), SELL, 100) == null); try std.testing.expect(inge.recoChek(aren.allocator(), "{\"kind\":\"face\",\"url\":\"http://x.com/1\",\"text\":\"a\"}", 20000) == null); try std.testing.expect(inge.recoChek(aren.allocator(), "{\"kind\":\"face\",\"url\":\"https://x.com/1\",\"text\":\"  \"}", 20000) == null); try std.testing.expect(inge.recoChek(aren.allocator(), "not json", 20000) == null); }
